        public static string Content = @"[{""AnnouncementType"":1,""Code"":""7276002"",""Contents"":[{""LanguageKey"":""en-US"",""Text"":""<span style =\""color: rgb(0, 0, 0); font-family: georgia; font-size: 18px;\"">Large screens printed with natural landscape bring breath-taking highlands landscapes and lush green forests teeming with exotic plants to the city's dusty corners. Tulip bulbs and sunflowers spring forth from flat, sunbaked displays throughout the central business district.&nbsp;</span>"",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""vi-VN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-CN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-TW"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""th-TH"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ko-KR"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ja-JP"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""}],""Id"":1,""IsActive"":false,""Specifications"":[],""Title"":""Fishing World - Super"",""Environments"":[""Local""],""Systems"":[""IBCBet""],""Ordinal"":1,""CreatedDate"":""2017-07-24T00:00:00-04:00"",""FromDate"":""2017-07-25T00:00:00-04:00"",""ToDate"":""2017-07-25T00:00:00-04:00""},{""AnnouncementType"":1,""Code"":""xxxx"",""Contents"":[{""LanguageKey"":""en-US"",""Text"":""<span style=\""color: rgb(0, 0, 0); font-family: georgia; font-size: 18px;\"">Some restaurants and shopping malls have gone one step further by throwing up images of trees and blossoms to recreate natural beauty.&nbsp;These panoramas did little to cool the city during the dry season swelter and, as the summer deluge gets going, they'll offer no roots to absorb rainwater or mitigate flooding.&nbsp;</span>"",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""vi-VN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-CN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-TW"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""th-TH"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ko-KR"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ja-JP"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""}],""Id"":2,""IsActive"":false,""Specifications"":[],""Title"":""continues to hack away at its already"",""Environments"":[""Local""],""Systems"":[""IBCBet""],""Ordinal"":1,""CreatedDate"":""2017-07-24T00:00:00-04:00"",""FromDate"":""2017-07-25T00:00:00-04:00"",""ToDate"":""2017-07-25T00:00:00-04:00""},{""AnnouncementType"":1,""Code"":""xxxx"",""Contents"":[{""LanguageKey"":""en-US"",""Text"":""<span style=\""color: rgb(0, 0, 0); font-family: georgia; font-size: 18px;\"">he doomed trees stand above a bright digital rendering of the riverside to come, though no deadline for the revitalization project has been announced. Until then, the city will have to satisfy itself with vinyl posters of everything it stands to gain in exchange for everything it's already lost.</span>"",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""vi-VN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-CN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-TW"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""th-TH"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ko-KR"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ja-JP"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""}],""Id"":3,""IsActive"":false,""Specifications"":[],""Title"":""On Ton Duc Thang Street"",""Environments"":[""Local""],""Systems"":[""IBCBet""],""Ordinal"":1,""CreatedDate"":""2017-07-24T00:00:00-04:00"",""FromDate"":""2017-07-25T00:00:00-04:00"",""ToDate"":""2017-07-25T00:00:00-04:00""},{""AnnouncementType"":1,""Code"":"""",""Contents"":[{""LanguageKey"":""en-US"",""Text"":""<p style=\""box-sizing: border-box; margin-bottom: 20px; font-family: georgia; color: rgb(0, 0, 0); font-size: 18px;\"">Saigon has&nbsp;announced a detailed plan to remove 258 towering hardwoods from Ton Duc Thang Street to make way for a new bridge to the Thu Thiem Peninsula.&nbsp;</p><p style=\""box-sizing: border-box; margin-bottom: 20px; font-family: georgia; color: rgb(0, 0, 0); font-size: 18px;\"">The tree clearance hasn't drawn the same opposition it did a few years ago. No petitions have been organized and many have&nbsp;<a title=\""What's your take on Saigon sacrificing over 250 trees for new bridge?\"" href=\""http://e.vnexpress.net/news/video/what-s-your-take-on-saigon-sacrificing-over-250-trees-for-new-bridge-3614047.html\"" target=\""_blank\"" style=\""box-sizing: border-box; color: rgb(0, 0, 0); text-decoration-line: none; outline: 1px;\""><span style=\""box-sizing: border-box; font-family: georgia !important; color: rgb(159, 34, 78);\"">even voiced support</span></a>&nbsp;for the effort to further develop the city.</p><p style=\""box-sizing: border-box; margin-bottom: 20px; font-family: georgia; color: rgb(0, 0, 0); font-size: 18px;\"">A month prior, during&nbsp;<a title=\""Saigon axes old trees to make way for first metro line\"" href=\""http://e.vnexpress.net/news/news/saigon-axes-old-trees-to-make-way-for-first-metro-line-3599177.html\"" target=\""_blank\"" style=\""box-sizing: border-box; color: rgb(0, 0, 0); text-decoration-line: none; outline: 1px;\""><span style=\""box-sizing: border-box; font-family: georgia !important; color: rgb(159, 34, 78);\"">a single afternoon</span></a>, leafy Le Loi Street was also clear-cut to make way for the city’s metro line.</p>"",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""vi-VN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-CN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-TW"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""th-TH"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ko-KR"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ja-JP"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""}],""Id"":4,""IsActive"":true,""Specifications"":[{""Value"":[2],""Id"":""e6cacf4d-37d8-4031-a17c-8b02600d4c3f"",""Name"":""User Level"",""Combinable"":true,""TypeName"":""Alpha.Announcements.Specs.UserLevelSpecification, Alpha.Announcements, Version=1.0.0.1, Culture=neutral, PublicKeyToken=null"",""ConjunctionOperator"":0,""SpecificationOperator"":1,""ValueRange"":null}],""Title"":""Razor.Testing"",""Environments"":[""Local""],""Systems"":[""IBCBet""],""Ordinal"":1,""CreatedDate"":""2017-07-24T00:00:00-04:00"",""FromDate"":""2017-07-24T00:00:00-04:00"",""ToDate"":""2017-07-24T00:00:00-04:00""},{""AnnouncementType"":2,""Code"":"""",""Contents"":[{""LanguageKey"":""en-US"",""Text"":""<span style=\""color: rgb(0, 0, 0); font-family: georgia; font-size: 18px;\"">Wedding gates sit on display along Nguyen Dinh Chieu Street (District 3). The flowery décor can be rented for between VND500,000 and 900,000 ($22-40), roughly 10 times cheaper than the real thing.</span>"",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""vi-VN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-CN"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""zh-TW"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""th-TH"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ko-KR"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""},{""LanguageKey"":""ja-JP"",""Text"":"""",""IsDisplayingByUrl"":false,""Url"":""""}],""Id"":5,""IsActive"":true,""Specifications"":[],""Title"":""razor testing 2"",""Environments"":[""Local""],""Systems"":[""IBCBet""],""Ordinal"":1,""Created